using (var cluster = new Cluster(new ClientConfiguration              {                  Servers = new List<Uri> { new Uri(Host) }              }))              {                  var authenticator = new PasswordAuthenticator(Username, Password);                  cluster.Authenticate(authenticator);                  var bucket = await cluster.OpenBucketAsync(DatabaseName);                  List<string> entityNames = (await cluster.QueryAsync<JObject>("select distinct `type` from `beer-sample`"))                      .Rows.Select(v => v.GetValue("type").ToString()).ToList();                    StringBuilder json = new StringBuilder();                  json.Append("{
");                  foreach (string name in entityNames)                  {                      json.Append(""").Append(name).Append("":
[");                      DataTable table = new DataTable(name);                        // get all rows of the table                      var objects = (await cluster.QueryAsync<JObject>($"select * from `{DatabaseName}` where type = "{name}"")).Rows.ToList();                      foreach (var jobj in objects)                      {                          json.Append(jobj.GetValue(DatabaseName).ToString());                          if (jobj != objects.Last())                              json.Append(",");                      }                      json.Append("]
");                      if (name != entityNames.Last())                          json.Append(",");                  }                  json.Append("}");                  var jsstring = json.ToString();                  JsonData = jsstring;                  return await base.CreateDataSetAsync(cancellationToken);              }

